questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: find-the-mistake pattern. er 1: step 2 uses qk(n+1)/4 (it stays in the same class on every list); er 2: step 4 uses the lower class limit; er 3: step 5 uses the cf of the quartile class itself. Source: original. */
P: [[[7,16,20,14,13,7],1],[[9,15,11,10,3,3],3],[[4,4,8,15,17,13],1],[[5,7,11,15,11,3],3],[[6,8,14,7,3,3],1],[[10,9,9,6,4,4],3],[[9,12,13,13,16,11],1],[[9,10,18,8,6,5],3],[[8,11,16,18,17,3],1],[[9,13,12,7,5,4],3]];
ix: 1+rand(10);
f: P[ix][1];
qk: P[ix][2];
lo1: rand([10,20]);
er: rand([1,2,3]);
w: 10;
L1: lo1-1/2;
cf: makelist(sum(f[i],i,1,t),t,1,length(f));
n: last(cf);
lcb: makelist(L1+(t-1)*w,t,1,length(f));
cb(p) := 1+length(sublist(cf,lambda([c],is(c<p))));
cfb(k) := if k=1 then 0 else cf[k-1];
gq(p) := lcb[cb(p)] + (p-cfb(cb(p)))/f[cb(p)]*w;
lo: makelist(lo1+(t-1)*w,t,1,6);
hi: makelist(lo1+t*w-1,t,1,6);
pos: qk*n/4;
kq: cb(pos);
q: gq(pos);
CF: cfb(kq); Fq: f[kq]; cfq: cf[kq]; Lq: lcb[kq];
posS: if er=1 then qk*(n+1)/4 else pos;
LS: if er=2 then lo[kq] else Lq;
CFS: if er=3 then cfq else CF;
shown: LS + (posS-CFS)/Fq*w;
posd: exd(posS);
Lsd: exd(LS);
shownd: dispdp(float(floor(10^1*(shown)+1/2)/10^1),1);
qd: dispdp(float(floor(10^1*(q)+1/2)/10^1),1);
cfstr: simplode(map(string,cf),", ");
opts: [["s1",false,"Step 1"],["s2",is(er=1),"Step 2"],["s3",false,"Step 3"],["s4",is(er=2),"Step 4"],["s5",is(er=3),"Step 5"],["s6",false,"Step 6"]];
/* test values */
wr1: if er=1 then "s4" else "s2";
qr: float(floor(10^1*(q)+1/2)/10^1);
qo: qr+3;
shownr: float(floor(10^1*(shown)+1/2)/10^1);
